    s.request({ at: 25, agentId, read: 9_000, w5m: 600, blocks: 2 })
    s.request({ at: 48, agentId, read: 9_600, w5m: 300 })
    s.request({ at: 7 * MIN, agentId, w5m: 9_900 }) // lapsed after a 6m12s gap at 5m
