    const s = new Session()
    s.request({ at: 0, w5m: 17_000 })
    s.request({ at: 40, read: 17_000, w5m: 600 })
    s.request({ at: 6 * MIN, w5m: 17_600 })
    s.request({ at: 6 * MIN + 30, read: 17_600, w1h: 900 })
    s.request({ at: 6 * MIN + 60, read: 18_500, w1h: 200 })
