    const s = new Session()
    s.request({ at: 0, w1h: 10_000 })
    s.request({ at: 20, read: 10_000, w1h: 500, tier: 'batch' })
    s.request({ at: 40, read: 10_500, w1h: 500, speed: 'fast' })
    s.request({ at: 60, read: 11_000, w1h: 500, tier: 'batch', speed: 'fast' })
