      ['unsafe', { input_tokens: 9_007_199_254_740_993, cache_read_input_tokens: 3_000, output_tokens: 10 }],
      ['split-negative', { input_tokens: 4, cache_creation_input_tokens: 10, cache_creation: { ephemeral_5m_input_tokens: -10, ephemeral_1h_input_tokens: 20 }, output_tokens: 10 }],
      ['split-not-object', { input_tokens: 4, cache_creation_input_tokens: 10, cache_creation: 10, output_tokens: 10 }],
      ['usage-array', [1, 2, 3] as unknown as Usage],
    ]
    let t = 20
    for (const [, rawUsage] of bad) {
      s.request({ at: t, rawUsage })
      t += 20
    }
    // Valid oddities: null (= 0), absent fields, integral float, exponent form.
    s.request({ at: t, rawUsage: { input_tokens: null, cache_read_input_tokens: 3e3, cache_creation_input_tokens: 100.0, output_tokens: 10, cache_creation: { ephemeral_1h_input_tokens: 100 } } })
    // NaN / Infinity literals are not JSON: those lines are malformed, and an
    // out-of-range exponent parses to Infinity, which is an invalid count.
    s.rawLine('{"type":"assistant","uuid":"a-nan","timestamp":"' + iso(t + 20) + '","message":{"id":"msg_nan","model":"claude-opus-5","usage":{"input_tokens":NaN}}}')
    s.rawLine('{"type":"assistant","uuid":"a-inf","timestamp":"' + iso(t + 21) + '","message":{"id":"msg_inf","model":"claude-opus-5","usage":{"input_tokens":1e400,"output_tokens":1}}}')
    s.request({ at: t + 40, read: 3_100, w1h: 50 })
    return s.text()
  },
}

function main(): void {
  for (const dir of ['synthetic', 'adversarial']) {
    const path = join(OUT_ROOT, dir)
    mkdirSync(path, { recursive: true })
    for (const stale of readdirSync(path)) rmSync(join(path, stale))
  }
  for (const [id, build] of Object.entries(fixtures)) {
    const path = join(OUT_ROOT, `${id}.jsonl`)
    writeFileSync(path, build())
    console.log(`wrote ${path}`)
  }
}

main()

