from pathlib import Path
p = Path('scripts/build-synthetic-fixtures.ts'); s = p.read_text()

def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (old[:60], s.count(old))
    s = s.replace(old, new)

rep('''interface Usage {
  input_tokens?: number | unknown
  cache_creation_input_tokens?: number | unknown
  cache_read_input_tokens?: number | unknown
  output_tokens?: number | unknown
  cache_creation?: { ephemeral_5m_input_tokens?: unknown; ephemeral_1h_input_tokens?: unknown } | unknown
  service_tier?: string
  speed?: string
  [extra: string]: unknown
}''', '''/** Raw `message.usage` as written to the log (deliberately loosely typed). */
type Usage = Record<string, unknown>''')
rep('''  sessionId?: string
  title?: string | null
  /** Rows appended''', '''  sessionId?: string
  /** Rows appended''')
rep("    const s = new Session({ title: null })\n", "    const s = new Session()\n")
# unknown-record-types: clean comments
rep('''    // A system row between the attachment and the assistant rows: the walk passes through it.
    s.raw({ ...s.common(), parentUuid: 'at-1', type: 'system', uuid: 'sys-1', timestamp: iso(31), content: poison('hook output'), subtype: 'hook' })
    s.request({ at: 30, read: 12_000, w1h: 400, parentOverride: 'sys-1' })
    // The system row above was written after the request's user/attachment rows
    // in the file; append the user/attachment rows for request 1 first is not
    // possible with this builder, so request 2 carries the same shape instead.
    s.raw({ ...s.common(), parentUuid: 'at-2', type: 'system', uuid: 'sys-2', timestamp: iso(61), content: poison('hook output'), subtype: 'hook' })
    s.request({ at: 60, read: 12_400, w1h: 350, parentOverride: 'sys-2' })''',
'''    // `system` rows sit inside the parentUuid chain (attachment → system →
    // assistant): the request-start walk must pass through a skipped row. The
    // builder writes the user/attachment rows after this row, which is fine —
    // the walk happens when the assistant row is ingested.
    s.raw({ ...s.common(), parentUuid: 'at-1', type: 'system', uuid: 'sys-1', timestamp: iso(31), content: poison('hook output'), subtype: 'hook' })
    s.request({ at: 30, read: 12_000, w1h: 400, parentOverride: 'sys-1' })
    s.raw({ ...s.common(), parentUuid: 'at-2', type: 'system', uuid: 'sys-2', timestamp: iso(61), content: poison('hook output'), subtype: 'hook' })
    s.request({ at: 60, read: 12_400, w1h: 350, parentOverride: 'sys-2' })''')
# BOM
rep("return '﻿' + lines[0]", "return '\\uFEFF' + lines[0]")
# hostile metadata with escapes
start = s.index("  'adversarial/hostile-metadata': () => {")
end = s.index("  'adversarial/prototype-pollution': () => {")
hostile = r'''  'adversarial/hostile-metadata': () => {
    // Every log-derived display string is hostile: control characters, ANSI
    // escapes, bidi overrides, markup, and lengths far past the clamp.
    const ESC = ''
    const long = (prefix: string) => prefix + 'x'.repeat(2_000)
    const s = new Session({
      cwd: `/tmp/${ESC}[31mred${ESC}[0m/<script>alert(1)</script>/‮evil/�bin`,
      gitBranch: long('feature/bell-'),
      sessionId: 'sess-�\r\n-ok',
    })
    s.aiTitle(`<img src=x onerror=alert(1)> ${ESC}]0;title${long('T')}`)
    s.request({ at: 0, w1h: 6_000, model: 'claude-opus-5' })
    s.request({ at: 20, read: 6_000, w1h: 200, effort: `${ESC}[1mhigh${ESC}[0m` })
    s.request({ at: 40, read: 6_200, w1h: 200, version: '2.1.251�' })
    s.request({ at: 60, read: 6_400, w1h: 200, model: long('claude-') })
    s.raw({ type: long('weird-type-'), payload: poison('x') })
    s.raw({ type: '�', payload: poison('y') })
    // Surrogate pairs straddling the clamp boundary in a title.
    s.aiTitle('\u{1F642}'.repeat(260))
    return s.text()
  },
'''
s = s[:start] + hostile + s[end:]
# prototype pollution: hand-written JSON so __proto__ is an own key
start = s.index("  'adversarial/prototype-pollution': () => {")
end = s.index("  'adversarial/invalid-numerics': () => {")
proto = r'''  'adversarial/prototype-pollution': () => {
    // `__proto__` / `constructor` / `prototype` keys at every level. Written
    // as raw JSON text: an object literal's `__proto__` is not an own key.
    const s = new Session()
    s.request({ at: 0, w1h: 4_000 })
    const common = JSON.stringify(s.common()).slice(1, -1)
    s.rawLine(
      `{${common},"type":"assistant","uuid":"a-polluted","parentUuid":"at-0","timestamp":"${iso(20)}",` +
        `"__proto__":{"polluted":true},"constructor":{"prototype":{"polluted":true}},` +
        `"message":{"id":"msg_polluted","model":"claude-opus-5","__proto__":{"model":"claude-haiku-4-5"},` +
        `"usage":{"input_tokens":4,"cache_read_input_tokens":4000,"cache_creation_input_tokens":100,"output_tokens":50,` +
        `"cache_creation":{"ephemeral_1h_input_tokens":100,"__proto__":{"ephemeral_5m_input_tokens":999}},` +
        `"constructor":"x","prototype":{"isPrototypeOf":1}}}}`,
    )
    s.rawLine('{"__proto__":{"type":"assistant"},"type":"mode"}')
    s.rawLine(`{"type":"user","uuid":"__proto__","parentUuid":"constructor","timestamp":"${iso(30)}"}`)
    s.rawLine(`{"type":"assistant","uuid":"a-proto-parent","parentUuid":"__proto__","timestamp":"${iso(33)}","message":{"id":"msg_proto_parent","model":"claude-opus-5","usage":{"input_tokens":4,"cache_read_input_tokens":4100,"output_tokens":20}}}`)
    s.request({ at: 40, read: 4_100, w1h: 100 })
    return s.text()
  },
'''
