    'sessionId',
    'title',
    'cwd',
    'gitBranch',
    'models',
    'versions',
    'efforts',
    'firstTimestamp',
    'lastTimestamp',
  ] as const) {
    const value = m[key]
    if (value !== undefined) metadata[key] = value as Json
  }
