2	 * WP-06 — golden-fixture cross-validation (docs/PLAN.md §5).
3	 *
4	 * Every fixture listed in `fixtures/fixtures.json` is parsed and analyzed by
5	 * the real engine and compared with the golden emitted by the independent
6	 * Python reference sim (`tools/refsim/refsim.py`). Neither side is the
7	 * oracle: a disagreement is settled by hand computation, never by copying
8	 * one side's number into the other.
9	 *
10	 * Also enforced here, per fixture:
11	 *  - the format-drift canary: the Claude Code versions a fixture carries
12	 *    must sit inside `VALIDATED_VERSION_RANGE`, except the one fixture the
13	 *    manifest marks `canaryExempt`, which must instead take the warn path;
14	 *  - the content-poison property: the CONTENT_POISON marker every fixture
15	 *    plants in conversation content never appears in any output;
16	 *  - the reconciliation property: the scenario at the observed TTL
17	 *    reproduces the actual cost;
18	 *  - manifest completeness: every committed `.jsonl` under `fixtures/` is
19	 *    listed (the generated 100MB fixture is git-ignored and excluded).
20	 */
21	
22	import { createReadStream, existsSync, readdirSync, readFileSync, statSync } from 'node:fs'
23	import { join, relative } from 'node:path'
24	import { Readable } from 'node:stream'
25	import { describe, expect, it } from 'vitest'
26	import { PRICING } from '../config/pricing'
27	import { VALIDATED_VERSION_RANGE, type AnalysisResult, type BucketAnalysis } from './contract'
28	import { knownModelIds } from './cost'
29	import { isVersionInValidatedRange, parseSession, rejectionReason } from './parser'
30	import { analyzeSession } from './simulator'
31	
32	const FIXTURES_ROOT = 'fixtures'
33	const MANIFEST_PATH = join(FIXTURES_ROOT, 'fixtures.json')
34	const GOLDEN_DIR = join(FIXTURES_ROOT, 'golden')
35	const GOLDEN_SCHEMA = 'cache-ttl-analyzer/golden/v1'
36	/** Planted by `scripts/build-synthetic-fixtures.ts` and `scripts/scrub-capture.py`. */
37	const CONTENT_POISON = 'POISON'
38	/**
39	 * Dollar figures are sums of per-token products; the two implementations
40	 * sum in different orders, so allow floating-point noise and nothing more.
41	 * (A single-token disagreement at the cheapest rate in the config —
42	 * Haiku 3.5 cache reads, $0.08/MTok — is 8e-8, three orders above this.)
43	 */
44	const USD_TOLERANCE = 1e-10
45	
46	interface ManifestEntry {
47	  path: string
48	  canaryExempt?: boolean
49	  trap?: string
50	  expect?: string
51	}
52	
53	interface Fixture extends ManifestEntry {
54	  id: string
55	  file: string
56	}
57	
58	type Json = null | boolean | number | string | Json[] | { [key: string]: Json }
59	
60	function loadFixtures(): Fixture[] {
61	  const manifest = JSON.parse(readFileSync(MANIFEST_PATH, 'utf8')) as { fixtures: ManifestEntry[] }
62	  const fixtures: Fixture[] = []
63	  for (const entry of manifest.fixtures) {
64	    const target = join(FIXTURES_ROOT, entry.path)
65	    if (statSync(target).isDirectory()) {
66	      for (const file of walk(target)) {
67	        const rel = relative(FIXTURES_ROOT, file).replaceAll('\\', '/')
68	        fixtures.push({ ...entry, id: rel.slice(0, -'.jsonl'.length), file })
69	      }
70	    } else {
71	      fixtures.push({ ...entry, id: entry.path.slice(0, -'.jsonl'.length), file: target })
72	    }
73	  }
74	  return fixtures
75	}
76	
77	function walk(dir: string): string[] {
78	  const out: string[] = []
79	  for (const name of readdirSync(dir).sort()) {
80	    const path = join(dir, name)
81	    if (statSync(path).isDirectory()) out.push(...walk(path))
82	    else if (name.endsWith('.jsonl')) out.push(path)
83	  }
84	  return out
85	}
86	
87	function goldenPath(id: string): string {
88	  return join(GOLDEN_DIR, `${id.replaceAll('/', '__')}.json`)
89	}
90	
91	async function runEngine(file: string) {
92	  const parsed = await parseSession(
93	    Readable.toWeb(createReadStream(file)) as ReadableStream<Uint8Array>,
94	    {
95	      fileName: 'session.jsonl',
96	      fileSizeBytes: statSync(file).size,
97	      knownModels: knownModelIds(PRICING),
98	    },
99	  )
100	  if (parsed.verdict === 'not-a-session-log') {
101	    return { parsed, result: undefined, reason: rejectionReason(parsed) }
102	  }
103	  return { parsed, result: analyzeSession(parsed, PRICING), reason: undefined }
104	}
105	
106	/** The golden's view of an `AnalysisResult` (mirrors `refsim.py` `analyze_file`). */
107	function project(result: AnalysisResult): Json {
108	  const m = result.metadata
109	  const metadata: Record<string, Json> = {}
110	  for (const key of [
111	    'sessionId',
112	    'title',
113	    'cwd',
114	    'gitBranch',
115	    'models',
116	    'versions',
117	    'efforts',
118	    'firstTimestamp',
119	    'lastTimestamp',
120	  ] as const) {
121	    const value = m[key]
122	    if (value !== undefined) metadata[key] = value as Json
123	  }
124	  return {
125	    outcome: 'analysis',
126	    metadata,
127	    parseStats: result.parseStats as unknown as Json,
128	    parseWarnings: result.parseWarnings as unknown as Json,
129	    buckets: result.buckets.map(projectBucket),
130	    unknownModels: result.unknownModels as unknown as Json,
131	  }
132	}
133	
134	function projectBucket(b: BucketAnalysis): Json {
135	  const out: Record<string, Json> = {
136	    bucket: b.bucket,
137	    threadCount: b.threadCount,
138	    requestCount: b.requestCount,
139	    actualCost: b.actualCost as unknown as Json,
140	    observedWriteSplit: b.observedWriteSplit as unknown as Json,
141	    observedTtl: b.observedTtl,
142	    configExplicitness: b.configExplicitness,
143	    scenarios: b.scenarios as unknown as Json,
144	    recommendation: b.recommendation,
145	    savingsUsd: b.savingsUsd,
146	    verdictSuppressed: b.verdictSuppressed,
147	    unpricedTokenShare: b.unpricedTokenShare,
148	    shape: b.shape as unknown as Json,
149	  }
150	  if (b.suppressionReason !== undefined) out.suppressionReason = b.suppressionReason
151	  return out
152	}
153	
154	/** Deep comparison collecting every difference, with a tolerance on floats. */
155	function diff(actual: Json, expected: Json, path: string, out: string[]): void {
156	  if (typeof expected === 'number' && typeof actual === 'number') {
157	    const close =
158	      Number.isInteger(expected) && Number.isInteger(actual)
159	        ? actual === expected
160	        : Math.abs(actual - expected) <= USD_TOLERANCE * Math.max(1, Math.abs(expected))
161	    if (!close) out.push(`${path}: engine ${actual} vs golden ${expected}`)
162	    return
163	  }
164	  if (Array.isArray(expected) || Array.isArray(actual)) {
165	    if (!Array.isArray(expected) || !Array.isArray(actual)) {
166	      out.push(`${path}: engine ${JSON.stringify(actual)} vs golden ${JSON.stringify(expected)}`)
167	      return
168	    }
169	    if (expected.length !== actual.length) {
170	      out.push(`${path}: length ${actual.length} vs golden ${expected.length}`)
171	    }
172	    const n = Math.min(expected.length, actual.length)
173	    for (let i = 0; i < n; i++) diff(actual[i], expected[i], `${path}[${i}]`, out)
174	    return
175	  }
176	  if (isObject(expected) && isObject(actual)) {
177	    const keys = new Set([...Object.keys(expected), ...Object.keys(actual)])
178	    for (const key of [...keys].sort()) {
179	      const childPath = path ? `${path}.${key}` : key
180	      if (!(key in actual)) out.push(`${childPath}: missing in engine output`)
181	      else if (!(key in expected)) out.push(`${childPath}: missing in golden`)
182	      else diff(actual[key], expected[key], childPath, out)
183	    }
184	    return
185	  }
186	  if (actual !== expected) {
187	    out.push(`${path}: engine ${JSON.stringify(actual)} vs golden ${JSON.stringify(expected)}`)
188	  }
189	}
190	
191	function isObject(value: Json): value is { [key: string]: Json } {
192	  return typeof value === 'object' && value !== null && !Array.isArray(value)
193	}
194	
195	const fixtures = loadFixtures()
196	
